  awaitPromise?: boolean | null;
  // JavaScript expression evaluated in the page's main frame, for example document.title or (() => ({href: location.href}))().
  expression: unknown;
  returnByValue?: boolean | null;
  // Exact collaborative browser tab to target, including a tab the user opened (see preview_status tabs). Omit to use this agent session's current tab, or the user's visible tab when this session has none.
  tabId?: string | null;
  [key: string]: unknown;
}): Promise<CallToolResult<{ toolIcon?: { _tag: "website"; faviconUrl?: string | null; faviconUrlDark?: string | null; pageUrl: string; [key: string]: unknown; } | { _tag: "native-app"; app: { _tag: "app-id"; appId: string; [key: string]: unknown; } | { _tag: "display-name"; displayName: string; [key: string]: unknown; }; [key: string]: unknown; } | { _tag: "themed-logo"; logoUrl: string; logoUrlDark?: string | null; [key: string]: unknown; } | null; value: unknown; [key: string]: unknown; }>>; };
```

